			if (identity === undefined) throw new Error(`Cannot verify the created output directory identity; refusing to remove ${path}`);
			let current;
			try {
				current = await lstat(path);
			} catch (cause) {
				if (cause instanceof Error && Reflect.get(cause, "code") === "ENOENT") return;
				throw cause;
			}
